(()=>{
'use strict';
const splash=document.getElementById('splash');
if(!splash)return;
const canvas=document.getElementById('samiIntroCanvas');
const ctx=canvas?.getContext('2d',{alpha:true});
const reduced=matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
const audio=document.getElementById('samiIntroAudio');
const soundBtn=document.getElementById('introSoundToggle');
let started=performance.now(),finished=false,surgeTimer=0,soundAllowed=true,audioStartedAt=0,handoffStarted=false;
const network={segments:[],nodes:[],maxD:1};
const pinStage=document.querySelector('.intro-pin-stage'),brandWrap=document.querySelector('.launch-brand-wrap');
function hashRand(seed){let x=Math.sin(seed*12.9898+78.233)*43758.5453;return x-Math.floor(x)}
function buildNetwork(){network.segments=[];network.nodes=[];let max=0;for(let b=0;b<30;b++){let a=hashRand(b+2)*Math.PI*2,x=0,y=0,d=0;const steps=7+Math.floor(hashRand(b+50)*7);for(let s=0;s<steps;s++){const len=24+hashRand(b*31+s*9)*52;const turn=hashRand(b*19+s*17);if(turn<.2)a+=Math.PI/2*(hashRand(s+b)>.5?1:-1);else if(turn<.47)a+=(hashRand(s*3+b)>.5?1:-1)*(.18+hashRand(b+s*8)*.36);const nx=x+Math.cos(a)*len,ny=y+Math.sin(a)*len*.34;d+=len;network.segments.push({x1:x,y1:y,x2:nx,y2:ny,d,branch:b,t:hashRand(b*101+s)});if(s%2===0)network.nodes.push({x:nx,y:ny,d,t:hashRand(900+b*11+s)});x=nx;y=ny;max=Math.max(max,d)}}network.maxD=max}
function resize(){if(!canvas||!ctx)return;const d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));ctx.setTransform(d,0,0,d,0,0)}
function easeOut(t){return 1-Math.pow(1-Math.max(0,Math.min(1,t)),3)}
function easeInOut(t){t=Math.max(0,Math.min(1,t));return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2}
function drawNetwork(progress,alpha,time,retract=false){if(!ctx||!canvas)return;const w=canvas.clientWidth,h=canvas.clientHeight,cx=w/2,cy=h*.505,scale=Math.min(w/950,h/520)*1.08,limit=network.maxD*Math.max(0,Math.min(1,progress));ctx.save();ctx.translate(cx,cy);ctx.lineCap='round';ctx.lineJoin='round';for(const s of network.segments){if(s.d>limit)continue;const local=Math.max(0,Math.min(1,(limit-s.d+90)/90)),flick=.82+.18*Math.sin(time*.004+s.t*19);ctx.globalAlpha=alpha*local*flick;ctx.strokeStyle=s.t>.58?'rgba(103,255,147,.95)':'rgba(37,239,200,.9)';ctx.lineWidth=(s.t>.84?1.2:.68)+(retract?.1:0);ctx.beginPath();ctx.moveTo(s.x1*scale,s.y1*scale);ctx.lineTo(s.x2*scale,s.y2*scale);ctx.stroke()}for(const n of network.nodes){if(n.d>limit||n.t<.58)continue;ctx.globalAlpha=alpha*.65;ctx.fillStyle='rgba(123,255,172,.9)';ctx.beginPath();ctx.arc(n.x*scale,n.y*scale,n.t>.88?1.5:.9,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawImpact(p,time){if(!ctx||!canvas||p<=0||p>=1.08)return;const w=canvas.clientWidth,h=canvas.clientHeight,cx=w/2,cy=h*.505;ctx.save();ctx.translate(cx,cy);const alpha=(1-Math.min(1,p))*0.46;for(let i=0;i<18;i++){const a=hashRand(i+43)*Math.PI*2,len=(28+hashRand(i+80)*145)*easeOut(Math.min(1,p*1.4)),j=(hashRand(i+120)-.5)*.5;ctx.globalAlpha=alpha*(.45+hashRand(i)*.55);ctx.strokeStyle=i%3?'rgba(86,255,151,.9)':'rgba(40,220,192,.82)';ctx.lineWidth=.7+hashRand(i+4)*.7;ctx.beginPath();ctx.moveTo(0,0);const mx=Math.cos(a+j)*len*.48,my=Math.sin(a+j)*len*.17;ctx.lineTo(mx,my);ctx.lineTo(Math.cos(a)*len,Math.sin(a)*len*.26);ctx.stroke()}ctx.globalAlpha=alpha*.55;ctx.strokeStyle='rgba(91,255,156,.8)';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,160*easeOut(p),37*easeOut(p),0,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawAmbient(time){if(!ctx||!canvas)return;const breath=.78+.22*Math.sin(time*.00045);drawNetwork(1,.032*breath,time);const w=canvas.clientWidth,h=canvas.clientHeight,cx=w/2,cy=h*.505,g=ctx.createRadialGradient(cx,cy,0,cx,cy,Math.min(w*.42,520));g.addColorStop(0,'rgba(61,255,158,.035)');g.addColorStop(.5,'rgba(20,185,167,.012)');g.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}

function startPinHandoff(){if(handoffStarted||!pinStage||!brandWrap)return;handoffStarted=true;splash.classList.add('pin-handoff');const sr=pinStage.getBoundingClientRect(),br=brandWrap.getBoundingClientRect();const fromX=sr.left+sr.width/2,fromY=sr.top+sr.height/2,targetX=br.left+br.width*.410,targetY=br.top+br.height*.665;const dx=targetX-fromX,dy=targetY-fromY;const targetPinH=br.height*.30,scale=Math.max(.22,Math.min(.42,targetPinH/104));pinStage.animate([{transform:'translate(-50%,-50%) scale(1)'},{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(${scale})`}],{duration:760,easing:'cubic-bezier(.18,.82,.2,1)',fill:'forwards'});}
function frame(now){if(!ctx||!canvas)return;ctx.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);const t=(now-started)/1000;if(!finished){const impact=(t-1.18)/.72;if(impact>0&&impact<1.08)drawImpact(impact,now);if(t>2.02&&t<3.73){const p=easeInOut((t-2.02)/1.55);drawNetwork(p,.10+.20*p,now)}else if(t>=3.73&&t<4.38){const p=1-easeInOut((t-3.73)/.54);drawNetwork(p,.24*p,now,true)}else if(t>=4.2)drawAmbient(now);if(t>=4.22)startPinHandoff();if(t>=5.48)completeIntro()}else drawAmbient(now);requestAnimationFrame(frame)}
function completeIntro(){if(finished)return;finished=true;splash.classList.add('intro-complete');splash.classList.remove('intro-running');scheduleSurge(1500);document.dispatchEvent(new CustomEvent('sami:introcomplete'))}
function scheduleSurge(delay){clearTimeout(surgeTimer);surgeTimer=setTimeout(()=>{if(!document.body.contains(splash)||splash.classList.contains('launching'))return;splash.classList.remove('brand-surge');void splash.offsetWidth;splash.classList.add('brand-surge');setTimeout(()=>splash.classList.remove('brand-surge'),720);scheduleSurge(3800+Math.random()*7600)},delay)}
function tryAudio(fromTouch=false){if(!audio||!soundAllowed)return;audio.volume=.42;if(audio.paused){if(fromTouch&&audioStartedAt&&performance.now()-audioStartedAt>4800)audio.currentTime=0;audio.play().then(()=>{audioStartedAt=performance.now();soundBtn?.classList.add('enabled');soundBtn?.setAttribute('aria-label','Mute launch sound')}).catch(()=>{soundBtn?.classList.add('ready')})}}
function toggleSound(){soundAllowed=!soundAllowed;localStorage.setItem('sami.launch.sound',soundAllowed?'on':'off');if(!soundAllowed){audio?.pause();soundBtn?.classList.remove('enabled');soundBtn?.classList.add('ready');soundBtn.textContent='♩';soundBtn?.setAttribute('aria-label','Enable launch sound')}else{soundBtn.textContent='♪';tryAudio(true)}}
function boot(){buildNetwork();resize();addEventListener('resize',resize,{passive:true});const fromMeet=new URLSearchParams(location.search).get('from')==='meet';soundAllowed=localStorage.getItem('sami.launch.sound')!=='off';if(soundBtn){soundBtn.textContent=soundAllowed?'♪':'♩';soundBtn.classList.add('ready');soundBtn.onclick=toggleSound}splash.classList.add('intro-running');if(fromMeet){started=performance.now()-5400;completeIntro();document.body.classList.add('from-meet')}else if(reduced){started=performance.now()-5400;completeIntro()}else{tryAudio(false);addEventListener('pointerdown',()=>tryAudio(true),{once:true,capture:true});requestAnimationFrame(frame)}}
window.SAMIIntro={complete:completeIntro,surge:()=>{splash.classList.add('brand-surge');setTimeout(()=>splash.classList.remove('brand-surge'),720)}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
